import manifest from '../data/generated/responsiveImages.json'

interface ResponsiveImageEntry {
  width: number
  height: number
  variants: [width: number, url: string][]
}

// JSON imports type arrays loosely, so state the shape the script writes.
const images = manifest as unknown as Record<string, ResponsiveImageEntry | undefined>

/**
 * `<img>` attributes that let the browser pick a WebP variant sized for the
 * device (generated by `npm run images`). `sizes` describes how wide the image
 * is rendered; the intrinsic width/height reserve its space before it loads.
 * Images without variants keep their original `src`.
 */
export function responsiveImageProps(src: string, sizes: string) {
  const entry = images[src]
  if (!entry) return { src }

  return {
    src,
    srcSet: entry.variants.map(([width, url]) => `${url} ${width}w`).join(', '),
    sizes,
    width: entry.width,
    height: entry.height,
  }
}

/**
 * `sizes` for the common layouts. The container stops growing at 96rem (1536px),
 * so above that the largest images never need more than its width.
 */
export const IMAGE_SIZES = {
  container: '(min-width: 96rem) 96rem, 100vw',
  halfContainer: '(min-width: 96rem) 48rem, (min-width: 48rem) 50vw, 100vw',
  halfFromDesktop: '(min-width: 96rem) 48rem, (min-width: 64rem) 50vw, 100vw',
  // Full-bleed split panel: object-cover fills a frame taller than the image's
  // 1.24:1 ratio (min 52rem desktop, 29rem mobile), so it renders wider than its column.
  splitPanel: '(min-width: 130rem) 50vw, (min-width: 64rem) 65rem, (min-width: 36rem) 100vw, 36rem',
  // Home case rows: the image fills the left half of the page from desktop up.
  homeCaseRow: '(min-width: 64rem) 50vw, 100vw',
} as const
